import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const CATALOG = {
  electronics: [{ id: "e1", name: "Чихэвч" }, { id: "e2", name: "Гар цаг" }],
  home: [{ id: "h1", name: "Аяга" }, { id: "h2", name: "Дэвсгэр" }, { id: "h3", name: "Дэр" }],
};
const fakeApi = (cat) => new Promise((res) => setTimeout(() => res(CATALOG[cat]), 200));

function App() {
  const [cat, setCat] = useState("electronics");
  const [items, setItems] = useState([]);

  useEffect(() => {
    let alive = true;
    fakeApi(cat).then((data) => { if (alive) setItems(data); });
    return () => { alive = false; };
  }, []); // энд бичнэ үү: cat өөрчлөгдөх бүрт дахин ачаалахын тулд хамаарлыг нэм

  return (
    <View style={styles.s}>
      <View style={styles.tabs}>
        <Pressable nativeID="cat-electronics" style={styles.tab} onPress={() => setCat("electronics")}><Text>Электрон</Text></Pressable>
        <Pressable nativeID="cat-home" style={styles.tab} onPress={() => setCat("home")}><Text>Гэр ахуй</Text></Pressable>
      </View>
      {items.map((it) => <Text key={it.id} testID="row" style={styles.row}>{it.name}</Text>)}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  tabs: { flexDirection: "row", gap: 10, marginBottom: 8 },
  tab: { backgroundColor: "#eef2ff", paddingHorizontal: 16, paddingVertical: 10, borderRadius: 999 },
  row: { fontSize: 16, paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
});

registerRootComponent(App);

